WITH filtered AS (SELECT *, CONCAT(device, ' - ', browser) AS device_browser, LENGTH(device) AS device_length, COALESCE(country, 'N/A') AS country_clean FROM sessions WHERE started_at >= TIMESTAMP '2023-07-16 12:00:00') SELECT dim.country AS customer_country, src.browser, COUNT(*) AS rows_total, MAX(src.device_length) AS max_device_length FROM filtered src LEFT JOIN customers dim ON src.customer_id = dim.id GROUP BY GROUPING SETS ((dim.country, src.browser), (dim.country), ());
